const { createParser, parse } = require('./src/csv');

const cases = [
  ['', []],
  ['\uFEFF', []],
  ['\n', [['']]],
  ['\n\n', [[''], ['']]],
  ['a\n', [['a']]],
  ['a,b\r\nc,d\re,f\ng', [['a', 'b'], ['c', 'd'], ['e', 'f'], ['g']]],
  [',', [['', '']]],
  ['a,', [['a', '']]],
  ['"a,b","c""d"\n', [['a,b', 'c"d']]],
  ['"x\r\ny\rz\n",1', [['x\r\ny\rz\n', '1']]],
  ['a"b,c"', [['a"b', 'c"']]],
  ['""', [['']]],
  ['"",""\r\n', [['', '']]],
  ['\uFEFFa,\uFEFFb', [['a', '\uFEFFb']]],
  ['\uD83D\uDE00,x', [['\uD83D\uDE00', 'x']]],
];

function chunked(text, cuts, opts) {
  const p = createParser(opts);
  const out = [];
  let prev = 0;
  for (const c of [...cuts, text.length]) {
    out.push(...p.push(text.slice(prev, c)));
    prev = c;
  }
  out.push(...p.end());
  return out;
}

for (const [text, expected] of cases) {
  assert.deepStrictEqual(parse(text), expected, JSON.stringify(text));
  for (let a = 0; a <= text.length; a++)
    for (let b = a; b <= text.length; b++)
      assert.deepStrictEqual(chunked(text, [a, a, b], undefined), expected, JSON.stringify([text, a, b]));
}

// Immediate emission at CR before LF arrives.
{
  const p = createParser();
  assert.deepStrictEqual(p.push('a\r'), [['a']]);
  assert.deepStrictEqual(p.push('\nb'), []);
  assert.deepStrictEqual(p.end(), [['b']]);
  assert.deepStrictEqual(p.end(), []);
  assert.throws(() => p.push(''), Error);
}

// Line numbers, including CRLF split across chunks and newlines inside quotes.
function lineOf(fn) {
  try { fn(); } catch (e) { assert(e instanceof SyntaxError); return /line (\d+)/.exec(e.message)[1]; }
  assert.fail('no throw');
}
const bad = 'a\r\n"x\r\ny\n\rz" ,q';
for (let k = 0; k <= bad.length; k++) {
  assert.strictEqual(lineOf(() => chunked(bad, [k])), '5', String(k));
}
assert.strictEqual(lineOf(() => parse('a\r\n"b\r\n')), '3');
const p2 = createParser();
p2.push('"a\r'); p2.push('\nb');
assert.strictEqual(lineOf(() => p2.end()), '2');

// Validation.
for (const d of ['', ',,', '"', '\r', '\n', 1, null]) assert.throws(() => createParser({ delimiter: d }), RangeError);
assert.deepStrictEqual(parse('a;b\n"c;d";e', { delimiter: ';' }), [['a', 'b'], ['c;d', 'e']]);
assert.deepStrictEqual(parse('a\tb', { delimiter: '\t', header: false }), [['a', 'b']]);
assert.throws(() => createParser().push(1), TypeError);
assert.deepStrictEqual(createParser({ header: true }).push('a\n'), [['a']]);

// Header mode.
assert.deepStrictEqual(parse('', { header: true }), []);
assert.deepStrictEqual(parse('x,x,__proto__\n1\n', { header: true }).map(o => ({ ...o })), [{ x: '1', x_2: '', __proto__: '' }].map(o => ({ ...o })));
const obj = parse('__proto__\nv', { header: true })[0];
assert.ok(Object.prototype.hasOwnProperty.call(obj, '__proto__'));
assert.strictEqual(Object.getPrototypeOf(obj), Object.prototype);
console.log('ok');

